package io.knowledgebrain.integration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.integration.api.enabled",havingValue="true") @RequestMapping("/api/spaces/{spaceId}/github/repositories")
final class GitHubController {
 private final GitHubStore store;private final GitHubClient remote;private final SpaceAuthorizationClient auth;private final MeterRegistry metrics;private final String origin;private final tools.jackson.databind.json.JsonMapper json=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 GitHubController(GitHubStore store,GitHubClient remote,SpaceAuthorizationClient auth,MeterRegistry metrics,@Value("${brain.integration.browser-origin}")String origin){this.store=store;this.remote=remote;this.auth=auth;this.metrics=metrics;this.origin=origin;}
 static String trace(HttpServletRequest r){var h=Collections.list(r.getHeaders("traceparent"));if(h.size()==1&&h.getFirst().matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")&&!h.getFirst().substring(3,35).equals("0".repeat(32))&&!h.getFirst().substring(36,52).equals("0".repeat(16)))return h.getFirst();return "00-"+UUID.randomUUID().toString().replace("-","")+"-"+UUID.randomUUID().toString().replace("-","").substring(0,16)+"-01";}
 static String one(HttpServletRequest r,String name){var h=Collections.list(r.getHeaders(name));if(h.size()!=1)throw GitHubRules.bad();return h.getFirst();}
 static long number(String raw,long fallback,long max){if(raw==null)return fallback;try{if(!raw.matches("[1-9][0-9]{0,18}"))throw GitHubRules.bad();long n=Long.parseLong(raw);if(n>max)throw GitHubRules.bad();return n;}catch(RuntimeException e){throw GitHubRules.bad();}}
 static void query(HttpServletRequest r,Set<String> keys){for(var p:r.getParameterMap().entrySet())if(!keys.contains(p.getKey())||p.getValue().length!=1)throw GitHubRules.bad();if(Set.of("GET","DELETE").contains(r.getMethod())&&(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null))throw GitHubRules.bad();}
 static long expected(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"ghr[1-9][0-9]{0,18}\""))throw GitHubRules.bad();return number(h.getFirst().substring(4,h.getFirst().length()-1),0,Long.MAX_VALUE);}
 UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw GitHubRules.bad();if(write&&(!origin.equals(one(r,"Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!"same-origin".equals(r.getHeader("Sec-Fetch-Site"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ambiguous session");token=c.getValue();}return auth.authorize(space,token,write,trace);}
 tools.jackson.databind.JsonNode body(HttpServletRequest r,int size)throws IOException{if(!"application/json".equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JSON required");byte[] data=r.getInputStream().readNBytes(size+1);if(data.length>size)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"GitHub input too large");try{var n=json.readTree(data);if(n==null||!n.isObject())throw GitHubRules.bad();return n;}catch(RuntimeException e){throw GitHubRules.bad();}}
 ResponseEntity<GitHubStore.Repository> response(GitHubStore.Repository value){return ResponseEntity.ok().eTag("\"ghr"+value.version()+"\"").cacheControl(CacheControl.noStore()).body(value);}
 @PostMapping ResponseEntity<GitHubStore.Repository> connect(@PathVariable String spaceId,HttpServletRequest r)throws IOException{query(r,Set.of());var space=GitHubRules.id(spaceId);var trace=trace(r);var actor=authorize(space,r,true,trace);String key=GitHubRules.key(one(r,"Idempotency-Key"));var n=body(r,1024);if(n.size()!=1||!n.path("url").isString())throw GitHubRules.bad();String url=GitHubRules.url(n.path("url").asString());var result=store.replay(space,actor,key,url);if(result==null){var source=remote.repository(url);if(!actor.equals(authorize(space,r,true,trace)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Principal changed");result=store.connect(space,actor,key,url,source,trace.substring(3,35));}metrics.counter("brain.integration.github.commands","type",result.replay()?"replay":"connect").increment();return ResponseEntity.status(result.replay()?200:201).eTag("\"ghr"+result.repository().version()+"\"").cacheControl(CacheControl.noStore()).body(result.repository());}
 @GetMapping ResponseEntity<GitHubStore.Page<GitHubStore.Repository>> list(@PathVariable String spaceId,HttpServletRequest r){query(r,Set.of("state","after","limit"));var space=GitHubRules.id(spaceId);authorize(space,r,false,trace(r));String state=Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE");UUID after=r.getParameter("after")==null?null:GitHubRules.id(r.getParameter("after"));metrics.counter("brain.integration.github.reads","type","repositories").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(space,state,after,(int)number(r.getParameter("limit"),20,100)));}
 @GetMapping("/{repositoryId}") ResponseEntity<GitHubStore.Repository> get(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){query(r,Set.of());var space=GitHubRules.id(spaceId);var id=GitHubRules.id(repositoryId);authorize(space,r,false,trace(r));return response(store.get(space,id));}
 @PostMapping("/{repositoryId}/sync") ResponseEntity<GitHubStore.Synced> sync(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r)throws IOException{query(r,Set.of());var space=GitHubRules.id(spaceId);var id=GitHubRules.id(repositoryId);String trace=trace(r);var actor=authorize(space,r,true,trace);String key=GitHubRules.key(one(r,"Idempotency-Key"));long expected=expected(r);if(body(r,32).size()!=0)throw GitHubRules.bad();var result=store.syncReplay(space,id,actor,key,expected);if(result==null){var repo=store.get(space,id);if(repo.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Repository changed; reload current state");if(!repo.state().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Repository disconnected");var source=remote.repository(GitHubRules.url(repo.url()));if(!source.externalId().equals(repo.externalId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"GitHub repository identity changed");var batch=remote.commits(source);if(!actor.equals(authorize(space,r,true,trace)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Principal changed");result=store.sync(space,id,actor,key,expected,batch,trace.substring(3,35));}metrics.counter("brain.integration.github.commands","type",result.replay()?"replay":"sync").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"ghr"+result.repository().version()+"\"").body(result);}
 @DeleteMapping("/{repositoryId}") ResponseEntity<GitHubStore.Repository> disconnect(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){query(r,Set.of());var space=GitHubRules.id(spaceId);var id=GitHubRules.id(repositoryId);String trace=trace(r);var actor=authorize(space,r,true,trace);var result=store.disconnect(space,id,actor,expected(r),trace.substring(3,35));metrics.counter("brain.integration.github.commands","type","disconnect").increment();return response(result);}
 @GetMapping("/{repositoryId}/commits") ResponseEntity<GitHubStore.Page<GitHubStore.Commit>> commits(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){query(r,Set.of("after","limit"));var space=GitHubRules.id(spaceId);var id=GitHubRules.id(repositoryId);authorize(space,r,false,trace(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.commits(space,id,r.getParameter("after")==null?null:GitHubRules.id(r.getParameter("after")),(int)number(r.getParameter("limit"),20,100)));}
 @GetMapping("/{repositoryId}/commits/{commitId}") ResponseEntity<GitHubStore.Commit> commit(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String commitId,HttpServletRequest r){query(r,Set.of());var space=GitHubRules.id(spaceId);var repo=GitHubRules.id(repositoryId);var id=GitHubRules.id(commitId);authorize(space,r,false,trace(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.commit(space,repo,id));}
 @GetMapping("/{repositoryId}/syncs") ResponseEntity<GitHubStore.SyncPage> syncs(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){
  query(r,Set.of("before","limit"));var space=GitHubRules.id(spaceId);var repo=GitHubRules.id(repositoryId);authorize(space,r,false,trace(r));
  Long before=r.getParameter("before")==null?null:number(r.getParameter("before"),0,Long.MAX_VALUE);int limit=(int)number(r.getParameter("limit"),20,100);
  var page=store.syncs(space,repo,before,limit);metrics.counter("brain.integration.github.reads","type","sync-history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(page);
 }
 @GetMapping("/{repositoryId}/revisions") ResponseEntity<List<GitHubStore.Revision>> history(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){query(r,Set.of("before","limit"));var space=GitHubRules.id(spaceId);var id=GitHubRules.id(repositoryId);authorize(space,r,false,trace(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,id,number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)number(r.getParameter("limit"),10,100)));}
}
